WITH valid AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, GREATEST(pressure, temp_c) greatest_pressure_temp_c, DATEDIFF(CURRENT_DATE(), reading_ts) days_since_reading_ts FROM device_readings WHERE reading_ts >= TO_TIMESTAMP('2025-09-01 10:00:00') AND temp_c >= 37) SELECT device_code, PERCENTILE_APPROX(humidity, 0.9) AS humidity_p90, SUM(CASE WHEN device_code = 'DV-02' THEN greatest_pressure_temp_c ELSE 0 END) AS dv_02_greatest_pressure_temp_c FROM valid GROUP BY device_code;
